scene:
let t=0;
const particles=[];
const NUM=70;
for(let i=0;i<NUM;i++){particles.push({x:Math.random()*W(),y:H()+Math.random()*200,r:1+Math.random()*2.3,speed:0.15+Math.random()*0.45,phase:Math.random()*Math.PI*2,alphaBase:0.25+Math.random()*0.45});}
function hexToRgba(hex,a){const v=hex.replace('#','');const r=parseInt(v.substring(0,2),16);const g=parseInt(v.substring(2,4),16);const b=parseInt(v.substring(4,6),16);return 'rgba('+r+','+g+','+b+','+a+')';}
function drawShellHalf(ctx,scale,dir,openAngle,color){
  ctx.save();
  ctx.rotate(dir*openAngle*0.3);
  ctx.beginPath();
  ctx.moveTo(0,0);
  for(let a=-0.9;a<=0.9;a+=0.05){
    const r=scale*30*(1-Math.abs(a)*0.15);
    const x=Math.sin(a)*r;
    const y=dir*Math.cos(a)*r*0.6;
    ctx.lineTo(x,y);
  }
  ctx.closePath();
  ctx.fillStyle=hexToRgba(color,0.32);
  ctx.fill();
  for(let a=-0.85;a<=0.85;a+=0.17){
    ctx.beginPath();
    ctx.moveTo(0,0);
    const r=scale*30;
    const x=Math.sin(a)*r;
    const y=dir*Math.cos(a)*r*0.6;
    ctx.lineTo(x,y);
    ctx.strokeStyle=hexToRgba(color,0.22);
    ctx.lineWidth=1;
    ctx.stroke();
  }
  ctx.restore();
}
function draw(){
  const w=W(), h=H();
  ctx.clearRect(0,0,w,h);
  t+=0.008;
  const cx=w/2, cy=h/2, safeR=Math.min(w,h)*0.22;
  for(let layer=0;layer<3;layer++){
    ctx.beginPath();
    const yBase=h*0.08+layer*14;
    const amp=6+layer*4;
    const freq=0.008+layer*0.002;
    for(let x=0;x<=w;x+=8){
      const y=yBase+Math.sin(x*freq+t*(0.6+layer*0.2))*amp;
      if(x===0) ctx.moveTo(x,y); else ctx.lineTo(x,y);
    }
    ctx.strokeStyle=hexToRgba(PALETTE[2],0.15+layer*0.05);
    ctx.lineWidth=1.2;
    ctx.stroke();
  }
  for(let layer=0;layer<3;layer++){
    ctx.beginPath();
    const yBase=h*0.92-layer*14;
    const amp=6+layer*4;
    const freq=0.007+layer*0.002;
    for(let x=0;x<=w;x+=8){
      const y=yBase+Math.sin(x*freq+t*(0.5+layer*0.2)+2)*amp;
      if(x===0) ctx.moveTo(x,y); else ctx.lineTo(x,y);
    }
    ctx.strokeStyle=hexToRgba(PALETTE[0],0.12+layer*0.04);
    ctx.lineWidth=1.2;
    ctx.stroke();
  }
  const shellX=w*0.82, shellY=h*0.86;
  const shellScale=Math.min(w,h)*0.0032;
  const openAngle=Math.min(1,t*0.15)*0.55;
  ctx.save();
  ctx.translate(shellX,shellY);
  drawShellHalf(ctx,shellScale,1,openAngle,PALETTE[1]);
  drawShellHalf(ctx,shellScale,-1,openAngle,PALETTE[1]);
  ctx.restore();
  const pearlX=shellX;
  const pearlY=shellY-shellScale*10;
  const pulse=1+Math.sin(t*1.4)*0.08;
  const pr=shellScale*16*pulse;
  const grad=ctx.createRadialGradient(pearlX-pr*0.3,pearlY-pr*0.3,pr*0.1,pearlX,pearlY,pr);
  grad.addColorStop(0,hexToRgba('#ffffff',0.95));
  grad.addColorStop(0.4,hexToRgba(PALETTE[1],0.9));
  grad.addColorStop(1,hexToRgba(PALETTE[2],0.4));
  ctx.save();
  ctx.shadowColor=hexToRgba(PALETTE[1],0.6);
  ctx.shadowBlur=25;
  ctx.beginPath();
  ctx.arc(pearlX,pearlY,pr,0,Math.PI*2);
  ctx.fillStyle=grad;
  ctx.fill();
  ctx.restore();
  for(let i=0;i<2;i++){
    const orbR=pr*(1.8+i*0.6);
    ctx.beginPath();
    ctx.ellipse(pearlX,pearlY,orbR,orbR*0.4,t*0.3+i,0,Math.PI*2);
    ctx.strokeStyle=hexToRgba(PALETTE[2],0.15-i*0.05);
    ctx.lineWidth=1;
    ctx.stroke();
  }
  for(const p of particles){
    p.y-=p.speed;
    if(p.y<-10){p.y=h+10;p.x=Math.random()*w;}
    const dx=p.x-cx, dy=p.y-cy;
    const dist=Math.sqrt(dx*dx+dy*dy);
    let alpha=p.alphaBase*(0.5+0.5*Math.sin(t*2+p.phase));
    if(dist<safeR){alpha*=(dist/safeR)*0.3;}
    ctx.beginPath();
    ctx.arc(p.x,p.y,p.r,0,Math.PI*2);
    ctx.fillStyle=hexToRgba(PALETTE[1],alpha);
    ctx.fill();
  }
  requestAnimationFrame(draw);
}
draw();
